<?php
require_once __DIR__ . '/../backend/middleware/RoleMiddleware.php';
require_once __DIR__ . '/../backend/security/Csrf.php';
require_once __DIR__ . '/../backend/services/PersonnelDataService.php';
$roleMiddleware = new RoleMiddleware(); $roleMiddleware->requireRole('staff');
$csrf = new Csrf(); $service = new PersonnelDataService(new Database()); $message = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!$csrf->valid($_POST['_csrf_token'] ?? null)) { $error = 'Your form session expired. Refresh and try again.'; }
    elseif ((int) ($_POST['farmer_id'] ?? 0) < 1 || trim((string) ($_POST['species'] ?? '')) === '') { $error = 'Farmer and species are required.'; }
    else { try { $service->addLivestock($_POST); $message = 'Livestock record saved.'; } catch (Throwable $exception) { error_log($exception->getMessage()); $error = 'Unable to save the livestock record.'; } }
}
$farmers = $service->farmers(); $livestock = $service->recent('livestock');
$pageTitle = 'Livestock - Personnel'; $pageDescription = 'Personnel livestock monitoring.'; $assetBase = 'assets'; $activePage = 'livestock'; require_once __DIR__ . '/../frontend/components/header.php'; require_once __DIR__ . '/../frontend/components/personnel-nav.php';
?>
<main class="min-h-screen bg-surface-container-low"><section class="max-w-container-max mx-auto px-gutter-mobile lg:px-gutter-desktop py-space-xl"><p class="text-xs uppercase tracking-wider text-primary font-bold">Farmer and livestock monitoring</p><h1 class="text-3xl font-extrabold mt-2">Livestock</h1><p class="text-sm text-on-surface-variant mt-2 mb-space-lg">Record livestock holdings linked to registered farmers.</p><?php if ($message): ?><div class="mb-4 rounded-lg border border-primary bg-primary/10 px-4 py-3 text-sm text-primary"><?= htmlspecialchars($message) ?></div><?php endif; ?><?php if ($error): ?><div class="mb-4 rounded-lg border border-error bg-error/10 px-4 py-3 text-sm text-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] gap-space-lg"><form method="post" class="bg-surface-container-lowest border border-surface-container rounded-lg p-space-lg space-y-4"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($csrf->token()) ?>"><h2 class="text-xl font-bold">Add livestock record</h2><select name="farmer_id" required class="form-input-custom w-full rounded-lg p-3 text-sm border border-outline-variant"><option value="">Select farmer</option><?php foreach ($farmers as $farmer): ?><option value="<?= (int) $farmer['id'] ?>"><?= htmlspecialchars($farmer['last_name'] . ', ' . $farmer['first_name']) ?></option><?php endforeach; ?></select><div class="grid grid-cols-2 gap-3"><input name="species" required placeholder="Species e.g. cattle" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="breed" placeholder="Breed" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><div class="grid grid-cols-2 gap-3"><input name="tag_number" placeholder="Tag number" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="quantity" type="number" min="1" value="1" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><div class="grid grid-cols-2 gap-3"><select name="sex" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><option value="unknown">Sex unknown</option><option value="male">Male</option><option value="female">Female</option></select><input name="birth_date" type="date" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><textarea name="notes" placeholder="Notes" class="form-input-custom w-full rounded-lg p-3 text-sm border border-outline-variant"></textarea><button class="rounded-lg bg-primary text-on-primary px-4 py-3 font-bold text-sm" type="submit">Save livestock</button></form><div class="bg-surface-container-lowest border border-surface-container rounded-lg overflow-hidden"><div class="p-space-lg border-b border-surface-container"><h2 class="text-xl font-bold">Recent livestock records</h2></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-surface-container-low text-xs uppercase"><tr><th class="p-3">Species</th><th class="p-3">Breed</th><th class="p-3">Quantity</th><th class="p-3">Status</th></tr></thead><tbody><?php foreach ($livestock as $item): ?><tr class="border-t border-surface-container"><td class="p-3 font-semibold"><?= htmlspecialchars($item['species']) ?></td><td class="p-3"><?= htmlspecialchars($item['breed'] ?? '-') ?></td><td class="p-3"><?= (int) $item['quantity'] ?></td><td class="p-3"><?= htmlspecialchars($item['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section></main><?php require_once __DIR__ . '/../frontend/components/footer.php'; ?>
